/**
 * Choosing versions by hand in real merges: real `git merge` conflicts,
 * lockfiles written and regenerated by the real npm CLI against a local
 * registry, then `--list` and `--pick`.
 */

import {strict as assert} from "assert"
import {test, describe, before, after} from "node:test"
import {readFile, writeFile} from "fs/promises"
import {join} from "node:path"
import {CLI_PATH, jsonLines, run, runCli, withTempDir, RunResult} from "./cli-harness.js"
import {FakeRegistry, fakeIntegrity, startFakeRegistry} from "./fake-registry.js"
import {validateLockfile} from "../lockfile-validator.js"

interface Repo {
  dir: string
  git(args: string[]): Promise<RunResult>
  npm(args: string[]): Promise<RunResult>
  cli(args: string[]): Promise<RunResult>
  /** Write package.json with these dependencies, lock it with npm and commit */
  commit(dependencies: Record<string, string>, message: string): Promise<void>
}

async function withRepo<T>(registry: FakeRegistry, fn: (repo: Repo) => Promise<T>): Promise<T> {
  return withTempDir(async dir => {
    const repo: Repo = {
      dir,
      git: args => run("git", args, dir),
      // npm is a .cmd shim on Windows, which needs a shell
      npm: args => run("npm", args, dir, registry.npmEnv, process.platform === "win32"),
      cli: args => runCli(args, dir, registry.npmEnv),
      async commit(dependencies, message) {
        await writeFile(
          join(dir, "package.json"),
          JSON.stringify({name: "app", version: "1.0.0", dependencies}, null, 2) + "\n"
        )
        const locked = await repo.npm(["install", "--package-lock-only", "--ignore-scripts"])
        assert.equal(locked.code, 0, locked.stderr)
        await repo.git(["add", "-A"])
        const committed = await repo.git(["commit", "-m", message])
        assert.equal(committed.code, 0, committed.stderr)
      },
    }

    await repo.git(["init", "-b", "main"])
    await repo.git(["config", "user.name", "Test"])
    await repo.git(["config", "user.email", "test@example.com"])
    return fn(repo)
  })
}

const readJson = async (dir: string, name: string) => JSON.parse(await readFile(join(dir, name), "utf8"))

describe("choosing versions in a real merge", () => {
  let registry: FakeRegistry
  before(async () => {
    registry = await startFakeRegistry({
      ms: ["2.1.1", "2.1.2", "2.1.3"],
      "left-pad": ["1.1.0", "1.1.3", "1.2.0", "1.3.0"],
    })
  })
  after(() => registry.close())

  test("git merge conflicts, --list, then --pick with the lockfile regenerated by npm", async () => {
    await withRepo(registry, async repo => {
      await repo.commit({ms: "2.1.1", "left-pad": "1.1.0"}, "base")
      await repo.git(["checkout", "-b", "feature"])
      await repo.commit({ms: "2.1.3", "left-pad": "1.3.0"}, "feature")
      await repo.git(["checkout", "main"])
      await repo.commit({ms: "2.1.2", "left-pad": "1.2.0"}, "main")

      const merge = await repo.git(["merge", "feature"])
      assert.equal(merge.code, 1, "both files conflict")
      assert.match(merge.stdout, /CONFLICT \(content\): Merge conflict in package\.json/)
      assert.match(merge.stdout, /CONFLICT \(content\): Merge conflict in package-lock\.json/)

      // What conflicts, and what each branch wants
      const listed = await repo.cli(["--list", "--json"])
      assert.equal(listed.code, 0, listed.stderr)
      const [report] = jsonLines(listed.stdout)
      const rows = report.files.map((file: any) => [
        file.file,
        file.packages.map((c: any) => `${c.name} ${c.location}: ${c.ours} | ${c.theirs}`),
      ])
      assert.deepEqual(rows, [
        ["package.json", ["left-pad dependencies: 1.2.0 | 1.3.0", "ms dependencies: 2.1.2 | 2.1.3"]],
        [
          "package-lock.json",
          [
            "left-pad root › dependencies: 1.2.0 | 1.3.0",
            "left-pad node_modules/left-pad: 1.2.0 | 1.3.0",
            "ms root › dependencies: 2.1.2 | 2.1.3",
            "ms node_modules/ms: 2.1.2 | 2.1.3",
          ],
        ],
      ])

      // ms from their branch, left-pad at a version neither branch has, lowest for the rest
      const resolved = await repo.cli(["--strategy", "lowest", "--pick", "ms@2.1.3", "--pick", "left-pad@1.1.3"])
      assert.equal(resolved.code, 0, `${resolved.stdout}\n${resolved.stderr}`)
      assert.match(resolved.stdout, /✅ ms@2\.1\.3 exists in the registry/)
      assert.match(resolved.stdout, /✅ left-pad@1\.1\.3 exists in the registry/)
      assert.match(
        resolved.stdout,
        /left-pad@1\.1\.3 is not locked on either branch of package-lock\.json; npm locks it when regenerating the lockfile/
      )
      assert.match(resolved.stdout, /Regenerated package-lock\.json/)

      const packageJson = await readJson(repo.dir, "package.json")
      assert.deepEqual(packageJson.dependencies, {ms: "2.1.3", "left-pad": "1.1.3"})
      const lockfile = await readJson(repo.dir, "package-lock.json")
      assert.equal(lockfile.packages["node_modules/ms"].version, "2.1.3")
      assert.equal(lockfile.packages["node_modules/ms"].integrity, fakeIntegrity("ms", "2.1.3"))
      assert.equal(lockfile.packages["node_modules/left-pad"].version, "1.1.3", "npm locked the picked version")
      assert.equal(lockfile.packages["node_modules/left-pad"].integrity, fakeIntegrity("left-pad", "1.1.3"))
      assert.deepEqual(validateLockfile(lockfile, packageJson), [])

      await repo.git(["add", "-A"])
      const committed = await repo.git(["commit", "--no-edit"])
      assert.equal(committed.code, 0, committed.stderr)
    })
  })

  test("with the merge driver installed, a git merge-file override leaves conflicts to pick from", async () => {
    await withRepo(registry, async repo => {
      await repo.git([
        "config",
        "merge.package-conflicts-resolver.driver",
        `"${process.execPath}" "${CLI_PATH}" merge-driver %A %O %B`,
      ])
      await writeFile(
        join(repo.dir, ".gitattributes"),
        "package.json merge=package-conflicts-resolver\npackage-lock.json merge=package-conflicts-resolver\n"
      )
      await repo.commit({ms: "2.1.1", "left-pad": "1.1.0"}, "base")
      await repo.git(["checkout", "-b", "feature"])
      await repo.commit({ms: "2.1.3", "left-pad": "1.1.0"}, "feature: bump ms")
      await repo.git(["checkout", "main"])
      await repo.commit({ms: "2.1.2", "left-pad": "1.2.0"}, "main: bump ms and left-pad")

      // The documented override: Git's own line merge, in diff3 style, instead of the driver
      const merge = await repo.git([
        "-c",
        "merge.package-conflicts-resolver.driver=git merge-file --diff3 -L HEAD -L base -L feature %A %O %B",
        "merge",
        "feature",
      ])
      assert.equal(merge.code, 1, `${merge.stdout}\n${merge.stderr}`)
      const markers = await readFile(join(repo.dir, "package.json"), "utf8")
      assert.match(markers, /^\|{7} base\r?$/m, "diff3 markers carry the common ancestor")

      // Only ms changed on both branches; left-pad changed on main only and merges cleanly
      const listed = await repo.cli(["--list", "--json"])
      assert.equal(listed.code, 0, listed.stderr)
      const [report] = jsonLines(listed.stdout)
      assert.deepEqual(
        report.files[0].packages.map((c: any) => [c.name, c.ours, c.theirs, c.base]),
        [["ms", "2.1.2", "2.1.3", "2.1.1"]]
      )

      const resolved = await repo.cli(["--pick", "ms@2.1.2"])
      assert.equal(resolved.code, 0, `${resolved.stdout}\n${resolved.stderr}`)
      const packageJson = await readJson(repo.dir, "package.json")
      assert.deepEqual(packageJson.dependencies, {ms: "2.1.2", "left-pad": "1.2.0"})
      const lockfile = await readJson(repo.dir, "package-lock.json")
      assert.equal(lockfile.packages["node_modules/ms"].version, "2.1.2")
      assert.equal(lockfile.packages["node_modules/left-pad"].version, "1.2.0")
      assert.deepEqual(validateLockfile(lockfile, packageJson), [])
    })
  })
})
